"""Question-specific drafting tasks, never legal facts or test expectations."""
import re
from response_guidance import is_document_request


def practical_response_focus(question, previous=''):
    """Task guidance only: never additional facts, law or an acceptance gate."""
    current = question.split('\nПредыдущий вопрос:')[0]
    context = current + '\n' + (previous or '')
    from retrieval_intents import consumer_quality_return_question,consumer_defect_remedy_question
    from retrieval_intents import civil_employment_comparison
    if civil_employment_comparison(current):
        return ('Сначала ответь, как соотносятся сообщённый гражданский договор и понятие зарплаты. '
                'Сопоставь переданное отличие трудового договора от иных договоров с условиями услуг или подряда. '
                'Не считай название договора окончательным доказательством вида отношений. '
                'Не заменяй сравнение только списком доказательств или советом запросить оплату. '
                'Трудовую процедуру взыскания автоматически не переноси на гражданское обязательство.')
    from retrieval_intents import image_author_rights_question
    if image_author_rights_question(current) and not is_document_request(current):
        return ('Сначала раздели разрешение автора произведения и правила использования изображения человека. '
                'Одно не объявляй автоматическим выполнением другого. Для каждого вывода используй свой переданный источник. '
                'Сохрани исключения статьи о собственном изображении и не обещай, что любая публикация разрешена. '
                'Исключение об оплатном позировании относится к самому изображённому лицу; не считай, что оно имело место без такого факта. '
                'Не добавляй непереданные требования к форме согласия или полномочиям фотографа.')
    from retrieval_intents import biometric_image_question
    if biometric_image_question(current) and re.search(r'личн|семейн|архив|прогулк', current, re.I):
        return ('Сначала сопоставь сообщённую пользователем цель обычной записи и обработку для установления личности. '
                'Не подменяй это сравнение просьбой собрать технические характеристики телефона. '
                'Используй переданную сферу действия закона и сведения об идентификаторах, сохрани условия и права других лиц. '
                'Не утверждай, что устройство выполняет или не выполняет распознавание, если это неизвестно. '
                'Различай личную запись и последующее использование или распространение изображения. '
                'Личная цель сама по себе не определяет вид данных и не доказывает отсутствие идентификации. '
                'Не выводи определение биометрических данных из статьи о сфере действия закона. '
                'Отдельно объясни переданное условие об использовании технологических средств в общественных местах; '
                'его нельзя безусловно переносить на любую семейную запись. '
                'Если точного определения в переданных положениях нет, кратко обозначь именно эту границу вывода, '
                'сохранив проверенные условия личных нужд и прав других лиц.')
    if consumer_defect_remedy_question(context):
        return ('Различи возможный недостаток и ситуацию, когда исправный товар просто не подошёл. Описание повреждения — сведения пользователя, не доказанная причина брака. '
                'По переданным статьям объясни применимые варианты и существенные условия; не переноси условие неиспользования на любые требования при недостатке. '
                'Не переноси специальные сроки для несоответствия стандартам на любую поломку. Предложи сохранить товар, описание дефекта и подтверждение покупки; не выдумывай результат проверки качества.')
    if re.search(r'КАСКО',context,re.I) and re.search(r'ОГПО|ОСАГО|обязательн.{0,30}ответственност',context,re.I):
        return ('Ответь отдельно о двух полисах: отказ по КАСКО не определяет покрытие по ОГПО. '
                'Различи собственный полис ответственности перед третьими лицами и страхование повреждения своего имущества по условиям договора. '
                'Не путай собственный ОГПО с возможным требованием потерпевшего к страховщику другого виновника. Не обещай выплату по описанию; сначала объясни различие, затем предложи проверить полис и мотивированный отказ.')
    if consumer_quality_return_question(context):
        return ('Сначала ответь на вопрос о возврате или обмене исправной вещи с учётом того, использовал ли её пользователь. '
                'Различи возврат товара надлежащего качества и требования при реальном недостатке или несоответствии. '
                'По найденной норме сохрани условия о неиспользовании, сохранности и применимые исключения; '
                'не обещай автоматический возврат, не объявляй ношеную вещь неисправной и не приписывай использование, если пользователь сообщил обратное. '
                'Не делай обратный абсолютный вывод, будто при любом использовании нет никаких прав. '
                'Отдельно предложи проверить фактическое состояние, подтверждение покупки и согласованные с продавцом условия.')
    from retrieval_intents import ordinary_image_scope
    if ordinary_image_scope(current):
        return ('Сначала ответь на вопрос о допустимости обычной фото- или видеосъёмки, а не о характеристиках камеры. '
                'Раздели фиксацию изображения и его использование/публикацию; объясни применимые пределы по переданным источникам. '
                'Не подменяй объяснение списком «сохраните/запросите». Биометрию и распознавание лиц не обсуждай без такого вопроса. '
                'Не превращай право получать информацию в безусловное разрешение снимать где угодно. '
                'Сопоставь также сферу действия закона о персональных данных: исключение из одного закона не отменяет отдельные права по Гражданскому кодексу. '
                'Исключения для онлайн-платформ не переноси на любую публикацию; сохрани все условия исключения, включая того, кто разместил сведения. '
                'Не добавляй правило о случайном прохожем или о любых должностных лицах из памяти другой юрисдикции. '
                'Если место или способ публикации меняют вывод, сначала объясни доступный общий принцип, затем задай одно уточнение.')
    if is_document_request(current):
        return ('Сразу дай редактируемый текст по текущей просьбе. Сохрани адресата и тему из контекста, '
                'неизвестные сведения оставь заполнителями. После текста предложи только проверку полей и сохранение копии. '
                'Не заменяй письмо списком действий и не добавляй новые требования или сроки для убедительности.')
    from response_guidance import is_reference_question
    if is_reference_question(current):
        extra = (' По переданным определениям различи общее понятие гражданского договора и отдельные виды договоров; '
                 'не своди общее понятие только к подряду или только к услугам.') if re.search(r'\bгпх\b|гражданско[ -]правов',current,re.I) else ''
        return ('Объясни термин простыми словами через его смысл для пользователя. '
                'Дай прямой подтверждённый ответ и существенную оговорку; не превращай определение в инструкцию по спору. '
                'Пример допустим только без придуманных ставок, сроков и правил.' + extra)
    base = ('Начни с решения текущей задачи, а не с пересказа документов. Для каждого предлагаемого действия '
            'покажи, что именно запросить или проверить и какой результат поможет выбрать следующий шаг. '
            'Начинай организационные шаги глаголом. Не повторяй вопросы, на которые пользователь уже ответил. ')
    if re.search(r'кредит|за[её]м|банк',context,re.I) and re.search(r'сравн|уменьш.{0,30}плат[её]ж|продл.{0,25}срок',current,re.I):
        return base + ('Предложи сопоставить старый и новый графики, общую сумму выплат, срок и отдельные расходы. '
                       'Без этих данных не делай вывода о выгодности предложения; не ограничивай сравнение одним платежом.')
    if re.search(r'аренд|залог|обеспечительн',context,re.I) and re.search(r'удерж|не возвращ|причин',context,re.I):
        return base + ('Для первого шага предложи запросить причины и расчёт удержания по пунктам, '
                       'сопоставить их с договором, актами и подтверждениями оплаты. Не обещай возврат всей суммы.')
    if re.search(r'банк|карт',context,re.I) and re.search(r'списа|комисси|удерж|непонятн.{0,20}плат[её]ж',context,re.I):
        return base + ('Помоги подготовить запрос о конкретной операции: назначение списания, расчёт и строка тарифа. '
                       'Не утверждай заранее, что списание незаконно или что возврат гарантирован.')
    return base + ('Дай применимые действия и не более двух уточнений, которые действительно изменят дальнейший совет. '
                   'Если подтверждена только часть ответа, сохрани её и отдельно назови недостающую деталь.')


def drafting_focus(question, previous, evidence):
    current = question.split('\nПредыдущий вопрос:')[0]
    context = current + '\n' + (previous or '')
    documents = {p.get('document_id') for p in evidence}
    tasks = []
    if 'credit-history' in documents and re.search(r'кредитн.{0,20}(?:истори|отч[её]т)|бюро|погашенн.{0,20}(?:кредит|за[её]м)', context, re.I):
        if is_document_request(current):
            tasks.append('Подготовь само заявление о проверке спорной записи: Кому, От, какая запись оспаривается, что проверить/исправить, перечень подтверждений, Дата и Подпись. Используй заполнители вместо личных данных. Просьбы не выдавай за гарантированный результат; достоверную историю не обещай удалить.')
        elif re.search(r'ошиб|неверн|недостовер|исправ|оспор|погаш|закрыт|просроч', current, re.I):
            tasks.append('Раздели спорную запись и доказательства её ошибочности, адресата проверки — бюро или поставщика сведений по переданным нормам — и запрос письменного результата. Не обещай автоматическое исправление или удаление всей кредитной истории.')
        elif re.search(r'получ|узна|скача|заказ|посмотр', current, re.I):
            tasks.append('Ответь о получении отчёта о себе: предложи официальный канал бюро или государственной услуги без непроверенной ссылки, объясни безопасную проверку личности через этот канал. Не проси присылать пароль, код или полный отчёт в чат. Не добавляй спор об ошибке, если его не спрашивали.')
    if ('collectors' in documents and re.search(r'чуж|родственник|знаком', current, re.I)
            and not re.search(r'угроз|насили', current, re.I)):
        tasks.append('Раздели контакт с третьим лицом и требование оплатить долг. Предложи запросить основание требования и проверить, какую роль в договоре приписывают пользователю; не выводи его обязанность или её отсутствие только из родства.')
    if 'shared-construction' in documents and re.search(r'документ|провер|каки.{0,15}способ', current, re.I):
        tasks.append('Сопоставь запрошенные документы с конкретным способом привлечения денег, описанным в источниках. Различай сведения о гарантии и разрешение там, где они предусмотрены; не требуй одновременно одинаковый комплект для любых схем. Предложи запросить название компании и способ привлечения денег без перевода оплаты до проверки.')
    if 'auto-insurance' in documents and re.search(r'удерж|выч[её]л|вычет|оценк.{0,20}расход|расход.{0,20}оценк', current, re.I):
        tasks.append('Разбери именно удержание из выплаты: предложи запросить расчёт и название удержанных расходов. Отдели собственные расходы страховщика на определение ущерба от иных возможных платежей. Правовую оценку дай только по соответствующей переданной норме, не по общему описанию страхового случая.')
    if 'joint-stock' in documents and re.search(r'дивиденд|доход|распределен', current, re.I):
        tasks.append('Сначала установи вид акций: общее описание решения по выплате не переноси автоматически на привилегированные акции. Сохрани отдельно подтверждённые условия и ограничения из источников; не перечисляй ненужные числовые сроки.')
    if 'digital-assets' in documents and re.search(r'отлич|разниц|сравн|вид[ыа]', current, re.I):
        tasks.append('Дай сравнение названных категорий по определениям из переданной редакции. Если термин в вопросе и термин в действующем фрагменте различаются, обозначь это различие, не подменяя одну классификацию другой. Не обещай доходность, гарантии государства или разрешённость любой площадки.')
    if 'family' in documents:
        from retrieval_intents import child_residence_question
        if child_residence_question(current):
            tasks.append('Сначала ответь на вопрос, решает ли ребёнок всё сам. Раздели учёт мнения и определение места жительства: для каждого вывода выбери именно свой фрагмент статьи. Для вывода из двух положений укажи оба источника. Сохрани исключение об интересах ребёнка. Не добавляй возраст или процедуру, которых нет в переданных выдержках.')
    if 'collectors' in documents and re.search(r'угро|насили|удар|запуг|пуга', current, re.I):
        tasks.append('Начни с безопасных организационных действий отдельными строками: «Обеспечьте свою безопасность при непосредственной угрозе»; «Свяжитесь с экстренной службой через официальный канал»; «Сохраните сообщения и обстоятельства угроз». Далее объясни только подтверждённые ограничения взыскания. Не добавляй неподтверждённые сроки, телефоны или гарантии. Условие не превращай в утверждение, что угроза уже доказана.')
    if 'nb-phishing-loan' in documents:
        tasks.append('Когда вопрос относится к подозрительному извещению о займе, предложи «Не переходите по ссылке из сообщения» и назови официальные каналы проверки, указанные в переданной памятке. Отдели меры защиты от процедуры исправления кредитного отчёта. Не объявляй любое уведомление доказанным мошенничеством.')
    context = current + '\n' + (previous or '')
    if 'labor' in documents and re.search(r'уволили|уволился|сократили|расторгли|договор расторгнут|после увольнения', context, re.I):
        tasks.append('При увольнении разбери отдельно основание прекращения, акт работодателя и расчёт выплат. Если спрашивают документы, предложи запросить копию акта и расшифровку начислений/удержаний/выплат, сохранить договор и подтверждения. Сроки и компенсации назови лишь при подтверждённом основании и источнике; не заменяй расчёт только вопросом о дате увольнения.')
    if 'tax' in documents and re.search(r'НДС|добавленн.{0,15}стоимост', context, re.I):
        tasks.append('Для ставки НДС различи дату договора, дату оборота/операции и применимую редакцию. Предложи проверить вид операции и переходные условия в источнике. Не выбирай ставку только по старой цифре в договоре; если переходное правило не передано, сохрани полезный список проверок без выдуманной ставки.')
    if re.search(r'начисл|на руки|зарплат', context, re.I) and re.search(r'точн.{0,15}расч[её]т|какие.{0,20}данн|какие.{0,20}сообщить', current, re.I):
        tasks.append('Пользователь просит данные для расчёта зарплаты: сохрани начисленную сумму из контекста, запроси период, вид договора, резидентство, применимые вычеты/льготы и обезличенную расшифровку. Не проси ИИН и не выдавай точную сумму на руки до определения условий.')
    if re.search(r'страхов|КАСКО|полис', context, re.I) and re.search(r'отказ|исключен', context, re.I):
        tasks.append('Различи вид страхования и конкретное основание отказа. Предложи запросить мотивированный письменный отказ с пунктом полиса, условия страхования на дату заключения, материалы события и расчёт. Не переноси исключения обязательного страхования на КАСКО и не обещай выплату только потому, что премия оплачена.')
    if 'mortgage' in documents:
        tasks.append('Не смешивай ипотечный залог квартиры в банке с обеспечительным платежом арендодателю. Раздели существование залога, право собственности и стадию обращения взыскания по переданным нормам. Для действий запроси договор, график, расчёт задолженности, текст уведомления и дату его получения; не обещай автоматический переход собственности или невозможность взыскания.')
    if re.search(r'реструктур', context, re.I):
        tasks.append('Ответь на текущий вопрос о реструктуризации: не заменяй вопрос о сохранении долга только инструкцией по жалобе. Правовой эффект отказа объясняй по источникам; организационно предложи проверить действующий график и письменное решение. В черновике сохрани явно сообщённые суммы и причины как сведения пользователя, без гарантии одобрения. Для обжалования сохрани первоначальное заявление, подтверждение подачи, ответ и договор; различай банк и МФО.')
    if is_document_request(current) and re.search(r'реструктур|кредит|за[её]м', context, re.I):
        from document_drafts import credit_payment_values
        proposed, existing = credit_payment_values(current)
        if proposed != '[сумма]' and existing != '[сумма]':
            tasks.append(f'В сообщении пользователь явно сообщил: текущий платёж {existing} тенге, посильный предлагаемый платёж {proposed} тенге. В черновике сохрани эти суммы с их разными ролями как сведения пользователя, не заменяй известные значения заполнителями и не выдавай предложение за одобренный график.')
    return tasks
